272	  /**
273	   * Each person's due-total in cents, by person id: the sum of their counted claims' due figures as
274	   * shown (each already rounded), skipping those that are n/a; 0 when none has a figure.
275	   */
276	  protected readonly dueCents = computed(() => {
277	    const out = new Map<number, number>();
278	    for (const p of this.people()) {
279	      const figures = this.claims
280	        .all()
281	        .filter((c) => c.personId === p.id && counts(c, p))
282	        .map((c) => this.rates.dueOf(c, gradeOn(p.grades, c.date)))
283	        .filter((c) => c !== undefined);
284	      out.set(p.id, figures.reduce((sum, c) => sum + c, 0));
285	    }
286	    return out;
287	  });
288	
289	  /** Everyone's due-total added up, skipping those that are n/a. */
290	  protected readonly dueTotalAll = computed(() =>
291	    formatCents([...this.dueCents().values()].reduce((sum, c) => sum + c, 0)),
292	  );
293	
294	  /**
295	   * Each person's overdue claims that count, by person id: how many, and their due figures added up
296	   * in cents, skipping those that are n/a.
297	   */
298	  private readonly overdueByPerson = computed(() => {
299	    const terms = this.session.terms() ?? 14;
300	    const today = this.session.today() ?? '';
301	    const out = new Map<number, { count: number; cents: number }>();
302	    for (const p of this.people()) {
303	      const late = this.claims.all().filter((c) => c.personId === p.id && counts(c, p) && overdue(c, terms, today));
304	      out.set(p.id, {
305	        count: late.length,
306	        cents: late.map((c) => this.rates.dueOf(c, gradeOn(p.grades, c.date)) ?? 0).reduce((sum, c) => sum + c, 0),
307	      });
308	    }
309	    return out;
310	  });
311	
312	  /** Everyone's overdue claims that count: how many, and their due-total in cents. */
313	  protected readonly overdueAll = computed(() =>
314	    [...this.overdueByPerson().values()].reduce(
315	      (all, o) => ({ count: all.count + o.count, cents: all.cents + o.cents }),
316	      { count: 0, cents: 0 },
317	    ),
318	  );
319	
320	  constructor() {
321	    effect((onCleanup) => {
322	      const drafts = this.withDrafts();
323	      this.keptListed.update((kept) => new Set([...kept, ...drafts]));
324	      const timer = setTimeout(() => this.keptListed.set(this.withDrafts()), LEAVE_DELAY_MS);
325	      onCleanup(() => clearTimeout(timer));
326	    });
327	    // Re-read the store each time the sheet is (re-)loaded.
328	    effect(() => {
329	      this.session.loads();
330	      untracked(() => {
331	        this.reset();
332	        this.importText.set('');
333	        this.importResult.set(null);
334	        this.importError.set(null);
335	        this.quickName.set('');
336	        this.quickAmount.set('');
337	        this.quickError.set(null);
338	        this.retireDates.set(new Map());
339	        this.rowError.set(null);
340	        this.patronChoices.set(new Map());
341	        this.patronError.set(null);
342	        void this.session.track(this.reload());
343	        void this.session.track(this.claims.reload());
344	      });
345	    });
346	  }
347	
348	  protected claimed(personId: number): string {
349	    return formatCents(this.claimedCents().get(personId) ?? 0);
350	  }
351	
352	  /** The person's grade in force on the sheet's today. */
353	  protected gradeToday(person: Person): Grade {
354	    return gradeOn(person.grades, this.session.today() ?? '');
355	  }
356	
357	  protected dueTotal(person: Person): string {
358	    const cents = this.dueCents().get(person.id);
359	    return cents === undefined ? 'n/a' : formatCents(cents);
360	  }
361	
362	  /** The names of the person's patrons, sorted, comma and space separated. */
363	  protected patronNames(person: Person): string {
364	    const byId = new Map(this.people().map((p) => [p.id, p.name]));
365	    return person.patronIds
366	      .map((id) => byId.get(id))
367	      .filter((n) => n !== undefined)
368	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
369	      .join(', ');
370	  }
371	
372	  /** The person's patrons' due-totals added up, skipping those that are n/a; 0.00 with no patrons. */
373	  protected backing(person: Person): string {
374	    const due = this.dueCents();
375	    return formatCents(person.patronIds.reduce((sum, id) => sum + (due.get(id) ?? 0), 0));
376	  }
377	
378	  protected patronChoice(personId: number): string {
379	    return this.patronChoices().get(personId) ?? '';
380	  }
381	
382	  protected setPatronChoice(personId: number, value: string): void {
383	    this.patronChoices.update((choices) => new Map(choices).set(personId, value));
384	    if (this.patronError()?.id === personId) this.patronError.set(null);
385	  }
386	
387	  /** Name the person chosen on the row as one of this person's patrons. */
388	  protected async addPatron(person: Person): Promise<void> {
389	    this.patronError.set(null);
390	    this.rowError.set(null);
391	    const patronId = Number(this.patronChoice(person.id));
392	    if (!patronId) {
393	      this.patronError.set({ id: person.id, message: 'Choose a person to name as a patron.' });
394	      return;
395	    }
396	    if (patronId === person.id) {
397	      this.patronError.set({ id: person.id, message: 'A person cannot be their own patron.' });
398	      return;
399	    }
400	    if (person.patronIds.includes(patronId)) {
401	      this.patronError.set({ id: person.id, message: 'That person is already a patron.' });
402	      return;
403	    }
404	    try {
405	      const saved = await this.api.addPatron(person.id, patronId);
406	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
407	      this.patronChoices.update((choices) => new Map(choices).set(person.id, ''));
408	    } catch (e) {
409	      this.patronError.set({
410	        id: person.id,
411	        message: e instanceof HttpErrorResponse && e.status === 409
412	          ? 'That person is already a patron.'
413	          : e instanceof HttpErrorResponse && e.status === 422
414	          ? 'A person cannot be their own patron.'
415	          : 'The patron could not be added.',
416	      });
417	    }
418	  }
419	
420	  protected overdueOf(personId: number): { count: number; cents: number } {
421	    return this.overdueByPerson().get(personId) ?? { count: 0, cents: 0 };
422	  }
423	
424	  protected retireDate(personId: number): string {
425	    return this.retireDates().get(personId) ?? this.session.today() ?? '';
426	  }
427	
428	  protected setRetireDate(personId: number, date: string): void {
429	    this.retireDates.update((dates) => new Map(dates).set(personId, date));
430	    if (this.rowError()?.id === personId) this.rowError.set(null);
431	  }
432	
433	  /** Retire the person from the date on their row (the sheet's today when left as it is). */
434	  protected async retire(person: Person): Promise<void> {
435	    this.rowError.set(null);
436	    this.patronError.set(null);
437	    const from = this.retireDate(person.id).trim();
438	    if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) {
439	      this.rowError.set({ id: person.id, message: 'Enter a date as yyyy-mm-dd.' });
440	      return;
441	    }
442	    try {
443	      const saved = await this.api.retire(person.id, from);
444	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
445	    } catch (e) {
446	      this.rowError.set({
447	        id: person.id,
448	        message: e instanceof HttpErrorResponse && e.status === 409
449	          ? 'This person is already retired.'
450	          : 'The person could not be retired.',
451	      });
452	    }
453	  }
454	
455	  /** Put the person on hold, or release them when they are held. */
456	  protected async toggleHold(person: Person): Promise<void> {
457	    this.rowError.set(null);
458	    this.patronError.set(null);
459	    try {
460	      const saved = await this.api.setHeld(person.id, !person.held);
461	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
462	    } catch (e) {
463	      this.rowError.set({
464	        id: person.id,
465	        message: e instanceof HttpErrorResponse && e.status === 409
466	          ? (person.held ? 'This person is not on hold.' : 'This person is already on hold.')
467	          : (person.held ? 'The person could not be released.' : 'The person could not be put on hold.'),
468	      });
469	    }
470	  }
471	
472	  protected edit(person: Person): void {
473	    this.editingId.set(person.id);
474	    this.editingVersion = person.version;
475	    this.name.set(person.name);
476	    this.grade.set(this.gradeToday(person));
477	    this.gradeFrom.set(this.session.today() ?? '');
478	    this.error.set(null);
479	  }
480	
481	  protected reset(): void {
482	    this.editingId.set(null);
483	    this.name.set('');
484	    this.grade.set('A');
485	    this.gradeFrom.set(this.session.today() ?? '');
486	    this.error.set(null);
487	  }
488	
489	  protected async save(event: Event): Promise<void> {
490	    event.preventDefault();
491	    if (this.saving) return;
492	    this.error.set(null);
493	    const fields = { name: this.name(), grade: this.grade() };
494	    if (!fields.name.trim()) {
495	      this.error.set('Enter a name.');
496	      return;
497	    }
498	    const gradeFrom = this.gradeFrom().trim();
499	    if (gradeFrom && !/^\d{4}-\d{2}-\d{2}$/.test(gradeFrom)) {
500	      this.error.set('Enter the grade\'s from-date as yyyy-mm-dd.');
501	      return;
502	    }
503	    const id = this.editingId();
504	    this.saving = true;
505	    try {
506	      if (id === null) {
507	        const added = await this.api.add(fields);
508	        this.people.update((list) => [...list, added]);
509	      } else {
510	        const saved = await this.api.update(id, this.editingVersion, { ...fields, gradeFrom });
511	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
512	      }
513	      this.reset();
514	    } catch (e) {
515	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
516	        await this.showCurrent(id);
517	        this.error.set('Someone else saved this person since you opened it. Their values are shown; open it again to edit.');
518	        return;
519	      }
520	      if (e instanceof HttpErrorResponse && e.status === 409) {
521	        this.error.set('That name is already in use on this sheet.');
522	        return;
523	      }
524	      this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
525	    } finally {
526	      this.saving = false;
527	    }
528	  }
529	
530	  protected async importPeople(event: Event): Promise<void> {
531	    event.preventDefault();
532	    if (this.importing) return;
533	    this.importResult.set(null);
534	    this.importError.set(null);
535	    this.importing = true;
536	    try {
537	      const result = await this.api.importLines(this.importText());
538	      this.importResult.set(result);
539	      if (result.added > 0 || result.updated > 0) {
540	        this.importText.set('');
541	        await this.reload();
542	      }
543	    } catch {
544	      this.importError.set('The people could not be imported.');
545	    } finally {
546	      this.importing = false;
547	    }
548	  }
549	
550	  /**
551	   * Add a DRAFT claim dated the sheet's today for the named person, adding the person (grade A)
552	   * first when the name is not on the sheet; the rules of the person and claim forms apply.
553	   */
554	  protected async quickAdd(event: Event): Promise<void> {
555	    event.preventDefault();
556	    if (this.quickAdding) return;
557	    this.quickError.set(null);
558	    const name = this.quickName().trim();
559	    const amount = this.quickAmount().trim();
560	    if (!name) {
561	      this.quickError.set('Enter a name.');
562	      return;
563	    }
564	    if (name.length > 100) {
565	      this.quickError.set('The name is too long.');
566	      return;
567	    }
568	    if (!AMOUNT.test(amount)) {
569	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
570	      return;
571	    }
572	    if (this.periods.closedOn(this.session.today() ?? '')) {
573	      this.quickError.set('Today is in a closed period, so no claim can be added.');
574	      return;
575	    }
576	    this.quickAdding = true;
577	    try {
578	      const added = await this.claims.quickAdd(name, amount);
579	      if (!this.people().some((p) => p.id === added.personId)) await this.reload();
580	      this.quickName.set('');
581	      this.quickAmount.set('');
582	    } catch (e) {
583	      this.quickError.set(e instanceof HttpErrorResponse && e.status === 423
584	        ? 'Today is in a closed period, so no claim can be added.'
585	        : e instanceof HttpErrorResponse && e.status === 422
586	        ? 'That person is retired before today, so no claim can be added.'
587	        : 'The claim could not be added.');
588	    } finally {
589	      this.quickAdding = false;
590	    }
591	  }
592	
593	  /** Re-read the store and show the person's current values in the form and in their row. */
594	  private async showCurrent(id: number): Promise<void> {
595	    await this.reload();
596	    const current = this.people().find((p) => p.id === id);
597	    if (current) {
598	      this.name.set(current.name);
599	      this.grade.set(this.gradeToday(current));
600	    }
601	  }
602	
603	  private async reload(): Promise<void> {
604	    try {
605	      this.people.set(await this.api.list());
606	    } catch {
607	      this.people.set([]);
608	    }
609	  }
610	}
